result:
.pointsMall{
	.title{
		font-size: 16px;
		color: #333;
		background-repeat: no-repeat;
		background-size: 100% 100%;
		width: 100%;
		height: 48px;
		display: flex
		justify-content: space-between
		align-items: center
		font-size: 16px;
		font-weight: 500;
		padding: 0 12px;
		img {
			width: 88px;
			height: 16px;
			display: block;
		}
		.more{
			font-size: 12px;
			color: #999;
			.iconfont{
				font-size: 12px;
			}
		}
	}
	.conter{
		padding: 0 0 16px 10px;
		background: linear-gradient(90deg, #E93323 0%, #FF7931 100%);
	}
	.list{
		background-color: #fff;
		padding: 10px 0 10px 10px;
		border-radius: 8px 0 0 8px;
		display: flex;
		overflow: hidden;
		&.on2{
			flex-wrap: wrap;
			padding-top: 0;
			.item{
				width: 47.4%;
				margin-right: 11px;
				margin-bottom: 10px;
				&:nth-of-type(2n){
					margin-right: 0;
				}
				&:nth-last-child(1),&:nth-last-child(2){
					margin-bottom: 0
				}
				.pictrue{
					width: 100%;
					height: 162px;
				}
				.name{
					font-size: 14px;
					margin-top: 5px;
				}
				.money{
					margin-top: 0;
					.num{
						&.on{
							font-size: 16px;
							font-family: D-DIN-PRO, D-DIN-PRO;
							font-weight: 600;
						}
					}
				}
			}
		}
		&.on{
			flex-wrap: wrap;
			padding-top: 0;
			.item{
				width: 30.7%;
				margin-right: 9px;
				margin-bottom: 10px;
				&:nth-last-child(1),&:nth-last-child(2),&:nth-last-child(3){
					margin-bottom: 0;
				}
				.pictrue{
					width: 100%;
					height: 106px;
				}
			}
		}
		.item{
			width: 112px;
			margin-right: 10px;
			.pictrue{
				width: 112px;
				height: 112px;
				background-color: #F3F9FF;
				img {
					width: 65px;
					height: 50px;
				}
			}
			.bottom{
				width: 98px;
				height: 18px;
				background: linear-gradient(90deg, #E93323 0%, #FF7931 100%);
				border-radius: 1px 10px 10px 10px;
				text-align: center;
				line-height: 18px;
				color: #fff;
				font-size: 11px;
				margin-top: 8px;
			}
			.money{
				font-size: 12px;
				color: #666;
				margin-top: 8px;
				img {
					width: 16px;
					height: 16px;
					display: block;
					margin-right: 4px;
				}
				.num{
					color: #E93323;
				}
			}
			.name{
				color: #282828;
				font-size: 13px;
				margin-top: 3px;
			}
		}
	}
}
